<?php require_once '../../config/conexion.php';$fecha=$_POST['fecha']??date('Y-m-d');$cliente=trim($_POST['cliente']??'');$producto=trim($_POST['producto']??'');$cantidad=(float)$_POST['cantidad'];$vehiculo=trim($_POST['vehiculo']??'');$piloto=trim($_POST['piloto']??'');$s=$conn->prepare('INSERT INTO despachos (fecha,cliente,producto,cantidad_m3,vehiculo,piloto) VALUES (?,?,?,?,?,?)');$s->bind_param('sssdss',$fecha,$cliente,$producto,$cantidad,$vehiculo,$piloto);$s->execute();header('Location: index.php');exit;
